contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: caller (unused because calls originate from this contract),
    // and a candidate newOwner address. We will attempt to call setOwner and observe whether it reverts
    // and the resulting owner value and return value when possible.
    function run(address newOwner) public payable {
        // Read owner before the deciding call
        address ownerBefore = c.owner();

        // Try to call setOwner and record whether it reverted and its return value if not reverted
        bool reverted;
        bool successReturn = false;
        try c.setOwner(newOwner) returns (bool ret) {
            reverted = false;
            successReturn = ret;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule asserted:
        // If the call reverted, owner must be unchanged. If the call did not revert, it must have returned true
        // and owner must equal the provided newOwner.
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && successReturn && ownerAfter == newOwner));
    }

    receive() external payable { }
}

