contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a candidate newOwner and a boolean indicating
    // whether to call setOwner as owner (true) or as non-owner (false).
    // We cannot change msg.sender when calling c from this contract, so to simulate
    // a non-owner call we first ensure owner is some address other than this contract
    // by attempting to set owner to another address while we are the owner (constructor of c made us owner).
    function run(address proposed, bool callAsOwner) public payable {
        require(proposed != address(0));
        // Read initial owner
        address ownerBefore = c.owner();

        // If we want to simulate a non-owner call, first transfer ownership away from this contract
        // by calling setOwner as the current owner (this contract is the initial owner of c).
        // That action must succeed only if msg.sender == ownerBefore (which should be true initially).
        // We choose a helper address that is different from this contract to be the new owner.
        address other = address(0x1234);
        if (!callAsOwner) {
            // make sure other is different from this contract to be a non-owner
            // perform top-level state-changing call
            bool ok1 = c.setOwner(other);
            // require it succeeded so subsequent call is truly from non-owner
            require(ok1);
        }

        // Now perform the deciding call as msg.sender == this contract
        bool reverted;
        try c.setOwner(proposed) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: if the call did not revert then caller must have been ownerBefore (i.e., this contract at that moment)
        // and ownerAfter must equal proposed. If the call reverted then ownerAfter must remain unchanged from before the call.
        assert((!reverted && ownerAfter == proposed) || (reverted && ownerAfter == ownerBefore) );
    }

    receive() external payable {}
}

