        // If the call did not revert, then the caller must have been the ownerBefore (i.e., ownerBefore == address(this)),
        // and the ownerAfter must equal the requested newOwner and the call must have returned success (non-revert).
        // We cannot observe the returned 'success' boolean when the call didn't revert because try-catch didn't capture the return value variable for use here,
        // but non-revert implies the function returned true per the contract. So assert the equivalence:
        // reverted == (ownerAfter == ownerBefore ? possibly true) but more precisely:
        // - If reverted then ownerAfter == ownerBefore.
        // - If not reverted then ownerBefore == address(this) && ownerAfter == newOwner.

        assert(
            (reverted && ownerAfter == ownerBefore) ||
            (!reverted && ownerBefore == address(this) && ownerAfter == newOwner)
        );
    }

    receive() external payable {}
}
